import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path from 'start' to 'end' in a directed weighted graph.

    Args:
        edges: List of (from_node, to_node, weight) tuples representing one-way roads.
        start: Starting node.
        end: Target node.

    Returns:
        A tuple (distance, path), where distance is the total edge weight and 
        path is a list of nodes from start to end.
        If no path exists: returns (None, None).
        If start == end: returns (0, [start]).

    Raises:
        ValueError: If any edge has a negative weight.
    """
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Edge with negative weight is not allowed")
        if from_node not in graph:
            graph[from_node] = {}
        graph[from_node][to_node] = weight

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    visited = set()
    pq = [(0, start)]
    paths = {node: [] for node in graph}
    paths[start] = [start]

    while pq:
        current_dist, u = heapq.heappop(pq)

        if u in visited:
            continue
        visited.add(u)

        if u == end:
            return (current_dist, paths[u])

        for v, w in graph.get(u, {}).items():
            new_dist = current_dist + w
            if new_dist < distances[v]:
                distances[v] = new_dist
                heapq.heappush(pq, (new_dist, v))
                paths[v] = paths[u] + [v]

    return (None, None)
